var SUPERCLASS_BY_ROOT = {
  clients: 'ApplicationClient',
  controllers: 'ApplicationController',
  jobs: 'ApplicationJob',
  mailers: 'ApplicationMailer',
  models: 'ApplicationRecord',
  procedures: 'ApplicationProcedure',
  services: 'ApplicationService',
  serializers: null // include JSONAPI::Serializer instead, see HEADER_BY_ROOT
};
var HEADER_BY_ROOT = { serializers: ['include JSONAPI::Serializer'] };

function camelize(segment) {
  return segment.split('_').map(function (p) { return p.charAt(0).toUpperCase() + p.slice(1); }).join('');
}

function railsWrapper(path, overrides) {
  overrides = overrides || {};
  var m = /^app\/([a-z_]+)\/(.+)\.rb$/.exec(path);
  if (!m) throw new Error('railsWrapper: not an app/<root>/**/*.rb path: ' + path);
  var root = m[1];
  var parts = m[2].split('/').map(camelize); // app/<root>/ itself is a Zeitwerk root dir, no module
  var className = parts.pop();
  var superclass = 'superclass' in overrides ? overrides.superclass
    : (root in SUPERCLASS_BY_ROOT ? SUPERCLASS_BY_ROOT[root] : null);
  var header = overrides.header || HEADER_BY_ROOT[root] || [];

  var before = '', after = '';
  parts.forEach(function (mod, i) { before += pad(i) + 'module ' + mod + '\n'; });
  var depth = parts.length;
  before += pad(depth) + 'class ' + className + (superclass ? ' < ' + superclass : '') + '\n';
  header.forEach(function (line) { before += pad(depth + 1) + line + '\n'; });
  if (header.length) before += '\n';
  for (var d = depth; d >= 0; d--) after += pad(d) + 'end\n';

  return {
    constant: parts.concat([className]).join('::'),
    superclass: superclass,
    before: before,
    after: after,
    indent: pad(depth + 1)
  };
}

function pad(level) { return new Array(level + 1).join('  '); }

function declaredConstant(source) {
  var names = [];
  var re = /^([ \t]*)(module|class)\s+([A-Z][A-Za-z0-9_:]*)/gm, mm;
  while ((mm = re.exec(source))) names.push({ indent: mm[1].length, kind: mm[2], name: mm[3] });
  var chain = [];
  for (var i = 0; i < names.length; i++) {
    if (names[i].indent !== chain.length * 2) break; // stop at first non-nesting declaration
    chain.push(names[i].name);
    if (names[i].kind === 'class') break;
  }
  return chain.join('::');
}

var body = $input.first().json.body || {};
var targetFile = body.targetFile || '';
var w = body.wrapper;
var wrapper, indent, wrapperError = null;
var expected = null;
try { expected = railsWrapper(targetFile, (w && typeof w === 'object' && w.auto) ? w : {}); } catch (e) { wrapperError = e.message; }
if (!w || w === 'auto' || w.auto) {
  // Derived from the path: the generator never writes module/class lines itself.
  wrapper = expected ? { before: expected.before, after: expected.after } : { before: '', after: '' };
  indent = expected ? expected.indent : '  ';
} else {
  wrapper = { before: w.before || '', after: w.after || '' };
  var declared = declaredConstant(wrapper.before);
  if (expected && declared !== expected.constant) {
    wrapperError = 'wrapper declares ' + declared + ' but Zeitwerk expects ' + expected.constant + ' for ' + targetFile + ' (omit wrapper to derive it automatically)';
  }
  var lines = wrapper.before.replace(/\n+$/, '').split('\n');
  var last = lines[lines.length - 1] || '';
  indent = /^[ \t]*/.exec(last)[0] + '  ';
}
return [{ json: {
  project: body.project || '',
  container: body.container || '',
  targetFile: targetFile,
  wrapper: wrapper,
  indent: indent,
  expectedConstant: expected ? expected.constant : null,
  wrapperError: wrapperError,
  errors: wrapperError ? [wrapperError] : [],
  pieces: body.pieces || [],
  systemPrompt: body.systemPrompt || 'You are a senior Ruby on Rails engineer working in this exact codebase. Follow the existing code style precisely. Output ONLY a single method, starting with def and ending with end. Never include a visibility keyword (private, public, protected), a surrounding class/module, or markdown fences -- just the raw def...end block.',
  rubyVersion: body.rubyVersion || '3.2'
} }];

var config = $('Normalize Input').first().json;
var pieceMeta = $('Split Pieces').all();
var outputs = $input.all();

function cleanPiece(raw) {
  var cleaned = (raw || '').replace(/^```[a-zA-Z]*\n?/, '').replace(/```\s*$/, '').trim();
  cleaned = cleaned.replace(/^(private|public|protected)\s*\n+/, '').trim();
  return cleaned;
}

var results = pieceMeta.map(function(m, i) {
  var piece = m.json.piece;
  var raw = (outputs[i] && outputs[i].json && outputs[i].json.output) || '';
  var cleaned = cleanPiece(raw);
  var valid = cleaned.indexOf('def ') === 0;
  return {
    name: piece.name,
    order: piece.order != null ? piece.order : i,
    prefix: piece.prefix || '',
    body: cleaned,
    valid: valid,
    reason: valid ? null : "response did not start with 'def ' after stripping markdown fences/visibility keyword"
  };
});

var invalid = results.filter(function(r) { return !r.valid; });
if (invalid.length > 0) {
  return [{ json: {
    valid: false,
    errors: invalid.map(function(r) { return r.name + ': ' + r.reason; }),
    pieceResults: results
  } }];
}

results.sort(function(a, b) { return a.order - b.order; });

function reindent(src, indent) {
  return src.split('\n').map(function(l) { return l.trim() === '' ? '' : indent + l; }).join('\n');
}

// Method indentation follows the real module/class nesting depth (was a fixed 2 spaces).
var indent = config.indent || '  ';
var body = results.map(function(r) {
  var prefixLine = r.prefix ? (indent + r.prefix.trim() + '\n\n') : '';
  return prefixLine + reindent(r.body, indent);
}).join('\n\n');

var content = config.wrapper.before + body + '\n' + config.wrapper.after;

return [{ json: {
  valid: true,
  content: content,
  pieceResults: results,
  targetFile: config.targetFile,
  container: config.container,
  expectedConstant: config.expectedConstant
} }];

var item = $json;
var scriptB64 = Buffer.from(item.content).toString('base64');
var sh = "mkdir -p \"$(dirname '" + item.targetFile + "')\" tmp/qwen_assemble && echo '" + scriptB64 + "' | base64 -d > tmp/qwen_assemble/candidate.rb && ruby -c tmp/qwen_assemble/candidate.rb && cp tmp/qwen_assemble/candidate.rb '" + item.targetFile + "'";
return [{ json: {
  targetFile: item.targetFile,
  content: item.content,
  dockerBridgePayload: { container: item.container, args: ['sh', '-c', sh] }
} }];

var resp = $input.first().json;
var targetFile = $('Build Write Command').first().json.targetFile;
var content = $('Build Write Command').first().json.content;
var ok = resp.exitCode === 0;
return [{ json: {
  filesWritten: ok ? 1 : 0,
  generatedFiles: ok ? [{ path: targetFile, content: content, language: 'ruby' }] : [],
  error: ok ? null : (resp.stderr || resp.stdout || ('docker-bridge exec failed, exitCode ' + resp.exitCode)),
  summary: ok ? ('1 fichier assemble et ecrit (' + targetFile + ')') : '0 fichier ecrit - echec syntaxe ou docker-bridge'
} }];

var item = $json;
return [{ json: {
  filesWritten: 0,
  generatedFiles: [],
  error: item.errors.join('; '),
  pieceResults: item.pieceResults,
  summary: '0 fichier ecrit - ' + item.errors.length + ' piece(s) invalide(s)'
} }];
